/**
 * Bivane · tweakcn 主题导出
 *
 * 用法：打开 tweakcn.com/editor/theme → Import → 粘贴本文件内容。
 *
 * ⚠ 本文件由 scripts/tweakcn-bridge.mjs 生成，勿手改。
 *   重新生成：npm run tweakcn:export
 */

:root {
  --background: #f7f8fa;
  --foreground: #323233;
  --card: #fff;
  --card-foreground: #323233;
  --popover: #fff;
  --popover-foreground: #323233;
  --primary: #1989fa;
  --primary-foreground: #fff;
  --secondary: #f2f3f5;
  --secondary-foreground: #323233;
  --muted: #f7f8fa;
  --muted-foreground: #969799;
  --accent: #f2f3f5;
  --accent-foreground: #323233;
  --destructive: #ee0a24;
  --destructive-foreground: #fff;
  --border: #ebedf0;
  --input: #ebedf0;
  --ring: #1989fa;
  --chart-1: #1989fa;
  --chart-2: #07c160;
  --chart-3: #ff976a;
  --chart-4: #ee0a24;
  --chart-5: #646566;
  --sidebar: #fff;
  --sidebar-foreground: #323233;
  --sidebar-primary: #1989fa;
  --sidebar-primary-foreground: #fff;
  --sidebar-accent: #f2f3f5;
  --sidebar-accent-foreground: #323233;
  --sidebar-border: #ebedf0;
  --sidebar-ring: #1989fa;
  --font-sans: -apple-system, BlinkMacSystemFont, "Helvetica Neue", Helvetica, "Segoe UI", Arial, Roboto, "PingFang SC", "miui", "Hiragino Sans GB", "Microsoft Yahei", sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, 'Times New Roman', Times, serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace;
  --radius: 4px;
  --shadow-color: #000000;
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 1px;
  --letter-spacing: 0px;
  --spacing: 16px;
}

.dark {
  --background: #000;
  --foreground: #f5f5f5;
  --card: #1c1c1e;
  --card-foreground: #f5f5f5;
  --popover: #1c1c1e;
  --popover-foreground: #f5f5f5;
  --primary: #1989fa;
  --primary-foreground: #fff;
  --secondary: #3a3a3c;
  --secondary-foreground: #f5f5f5;
  --muted: #000;
  --muted-foreground: #707070;
  --accent: #3a3a3c;
  --accent-foreground: #f5f5f5;
  --destructive: #ee0a24;
  --destructive-foreground: #fff;
  --border: #3a3a3c;
  --input: #3a3a3c;
  --ring: #1989fa;
  --chart-1: #1989fa;
  --chart-2: #07c160;
  --chart-3: #ff976a;
  --chart-4: #ee0a24;
  --chart-5: #646566;
  --sidebar: #1c1c1e;
  --sidebar-foreground: #f5f5f5;
  --sidebar-primary: #1989fa;
  --sidebar-primary-foreground: #fff;
  --sidebar-accent: #3a3a3c;
  --sidebar-accent-foreground: #f5f5f5;
  --sidebar-border: #3a3a3c;
  --sidebar-ring: #1989fa;
  --font-sans: -apple-system, BlinkMacSystemFont, "Helvetica Neue", Helvetica, "Segoe UI", Arial, Roboto, "PingFang SC", "miui", "Hiragino Sans GB", "Microsoft Yahei", sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, 'Times New Roman', Times, serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace;
  --radius: 4px;
  --shadow-color: #000000;
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 1px;
  --letter-spacing: 0px;
  --spacing: 16px;
}

#!/usr/bin/env node
/**
 * Bivane · tweakcn 双向桥接器
 *
 * 两个方向：
 *   export  Bivane token  →  tweakcn 可导入的 CSS（贴进 tweakcn 的 Import Custom CSS）
 *   import  tweakcn CSS   →  Bivane 品牌风格类（.bv-theme-xxx，贴进自己的项目）
 *
 * ── 为什么需要它 ────────────────────────────────────────────────
 * tweakcn 的导入器（源码 utils/parse-css-input.ts）只认两样东西：
 *   1. 字面量的 `:root { … }` 与 `.dark { … }` 两个块
 *   2. 44 个 shadcn 风格变量名（--primary / --background / …）
 * Bivane 的 CSS 写的是 `:root, :host { … }` 与 `.bv-theme-dark { … }`，
 * 变量名全是 `--bv-*` —— 直接丢进去，tweakcn 会**静默导入 0 个变量**，
 * 表现为「导入成功但一个颜色都没变」。这个脚本就是补上这层翻译。
 *
 * ── 关键约束 ────────────────────────────────────────────────────
 * · 颜色必须是**字面量**（hex/hsl/oklch），不能是 var() 引用 ——
 *   tweakcn 交给 culori 解析，var() 会解析失败并被静默丢弃。
 * · 产物必须用**字面量** `:root` / `.dark` 选择器，不能用 `:root, :host`。
 * · 导入产物只覆盖**品牌槽**，不动中性槽（理由见 mapping.mjs 的注释）。
 *
 * 用法：
 *   node scripts/tweakcn-bridge.mjs export  [--out <file>]
 *   node scripts/tweakcn-bridge.mjs import  <tweakcn.css> --name <name> [--out <file>]
 */

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import {
    CHART_ROLE,
    TO_BIVANE,
    TO_TWEAKCN,
    TWEAKCN_COLOR_SLOTS,
    TWEAKCN_SLOTS,
} from './tweakcn/mapping.mjs';
import {
    collectScopes,
    extractBlocks,
    extractDecls,
    isColorLiteral,
    resolveVar,
} from './tweakcn/css-vars.mjs';
import { normalizeColor } from './tweakcn/color.mjs';
import { parseCssInput } from './tweakcn/tweakcn-parser.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const STYLES_DIR = join(ROOT, 'packages/tokens/styles');

/** Bivane 的基座作用域选择器（vant.css 用的是 `:root, :host`） */
const BASE_SCOPE = ':root, :host';

/** 深色主题的作用域选择器 */
const DARK_SCOPE = '.bv-theme-dark';

/**
 * 读取 Bivane 的 token 表。
 *
 * @param {string[]} extraFiles 额外并入的 CSS（用于把某个风格当作基座导出）
 * @returns {{base: Record<string,string>, dark: Record<string,string>, style: Record<string,string>}}
 */
export function readBivaneTokens(extraFiles = []) {
    const base = collectScopes(
        [readFileSync(join(STYLES_DIR, 'vant.css'), 'utf8')],
        [BASE_SCOPE],
    )[BASE_SCOPE] ?? {};

    const dark = {
        ...base,
        ...(collectScopes([readFileSync(join(STYLES_DIR, 'vant-dark.css'), 'utf8')], [DARK_SCOPE])[
            DARK_SCOPE
        ] ?? {}),
    };

    // 风格文件（vant-ocean.css / vant-grape.css）的作用域形如 `.bv-theme-ocean`
    const style = {};
    for (const file of extraFiles) {
        const css = readFileSync(file, 'utf8');
        const scopes = collectScopes(
            [css],
            [...new Set([...extractBlocks(css).keys()].filter((s) => s.startsWith('.bv-theme-')))],
        );
        for (const body of Object.values(scopes)) Object.assign(style, body);
    }

    return { base, dark, style };
}

/**
 * 导出：把 Bivane 的 token 翻译成 tweakcn 可导入的 CSS。
 *
 * @param {Record<string,string>} scope  当前作用域的 token 表（已含深色或风格覆盖）
 * @param {'light'|'dark'} mode
 * @returns {string}  tweakcn 格式的 CSS 片段
 */
export function exportTweakcnCss(scope, mode) {
    const lines = [];
    for (const slot of TWEAKCN_SLOTS) {
        const source = TO_TWEAKCN[slot];
        let value;
        if (source.startsWith('literal:')) {
            value = source.slice('literal:'.length);
        } else {
            value = resolveVar(scope, source);
            if (value === null) continue; // 该作用域缺这个槽 → 跳过（tweakcn 会用默认值）
        }
        // 颜色槽必须是合法颜色字面量，否则 tweakcn 的 culori 解析失败会静默丢弃
        if (TWEAKCN_COLOR_SLOTS.includes(slot) && !isColorLiteral(value)) {
            throw new Error(
                `导出中止：槽 ${slot}（来源 ${source}）解析出的 "${value}" 不是合法颜色字面量。` +
                    `tweakcn 会把它静默丢弃。`,
            );
        }
        // 折叠内部空白：vant.css 里 --bv-base-font 是多行写的，导出产物要单行
        // （多行值在 tweakcn 的正则里虽能匹配，但产物可读性差、且可能被别的工具截断）
        lines.push(`  --${slot}: ${value.replace(/\s+/g, ' ').trim()};`);
    }
    const selector = mode === 'dark' ? '.dark' : ':root';
    return `${selector} {\n${lines.join('\n')}\n}`;
}

/**
 * 组装完整的导出产物：浅色 :root + 深色 .dark。
 *
 * @param {{base:object, dark:object, style:object}} tokens
 * @param {{name?:string, includeDark?:boolean}} opts
 */
export function buildExport(tokens, opts = {}) {
    const name = opts.name ?? 'Bivane';
    const includeDark = opts.includeDark !== false;

    // 风格覆盖品牌槽：把风格表的品牌槽并进作用域
    const lightScope = { ...tokens.base, ...tokens.style };
    // 深色作用域 = 深色表（含深色中性槽） + 风格品牌槽
    const darkScope = { ...tokens.dark, ...tokens.style };

    const parts = [
        `/**`,
        ` * ${name} · tweakcn 主题导出`,
        ` *`,
        ` * 用法：打开 tweakcn.com/editor/theme → Import → 粘贴本文件内容。`,
        ` *`,
        ` * ⚠ 本文件由 scripts/tweakcn-bridge.mjs 生成，勿手改。`,
        ` *   重新生成：npm run tweakcn:export`,
        ` */`,
        ``,
        exportTweakcnCss(lightScope, 'light'),
    ];
    if (includeDark) {
        parts.push(``, exportTweakcnCss(darkScope, 'dark'));
    }
    const css = parts.join('\n') + '\n';

    // ── 写出前自查 ────────────────────────────────────────────────
    // 用 tweakcn 自己的解析器回读一遍产物，确认 44 个槽都在、颜色都是字面量。
    // 这道闸门挡住的是「文件看着对、tweakcn 读不出来」的静默失败 ——
    // 那正是桥接最初要解决的问题，不能自己再犯一遍。
    assertExportIsImportable(css);

    return css;
}

/**
 * 自查：产物必须能被 tweakcn 的真实解析器完整读出。
 *
 * 依赖 packages/tokens/tweakcn/tweakcn-parser.mjs（tweakcn 源码的逐字复刻）。
 */
export function assertExportIsImportable(css) {
    const { lightColors, darkColors } = parseCssInput(css);

    for (const [mode, colors] of [
        ['浅色', lightColors],
        ['深色', darkColors],
    ]) {
        const missing = TWEAKCN_SLOTS.filter((s) => !(s in colors));
        if (missing.length) {
            throw new Error(
                `导出自查失败：${mode}块有 ${missing.length} 个槽 tweakcn 读不出来（${missing.join(', ')}）。` +
                    `这会导致「导入成功但颜色没变」。`,
            );
        }
        for (const slot of TWEAKCN_COLOR_SLOTS) {
            if (!isColorLiteral(colors[slot])) {
                throw new Error(
                    `导出自查失败：${mode}块的 --${slot} = "${colors[slot]}" 不是合法颜色字面量，` +
                        `tweakcn 的 culori 会解析失败并静默丢弃。`,
                );
            }
        }
    }
}

/**
 * 导入：把 tweakcn 导出的 CSS 翻译回 Bivane 品牌风格类。
 *
 * @param {string} css       tweakcn 导出的 CSS
 * @param {string} className 生成的类名（不含点）
 * @returns {string} Bivane 风格类 CSS
 */
export function importTweakcnCss(css, className) {
    const blocks = extractBlocks(css);
    const light = {};
    const dark = {};
    for (const [selector, bodies] of blocks) {
        if (selector !== ':root' && selector !== '.dark') continue;
        const bucket = selector === ':root' ? light : dark;
        for (const body of bodies) Object.assign(bucket, extractDecls(body));
    }

    const total = Object.keys(light).length + Object.keys(dark).length;
    if (total === 0) {
        throw new Error(
            '导入中止：没能从输入里解析出任何 tweakcn 变量。\n' +
                'tweakcn 的 CSS 必须包含字面量的 `:root { … }` 块（深色用 `.dark { … }`），\n' +
                '变量名限 --primary / --background / --muted 等 44 个 shadcn 风格名。',
        );
    }

    // 品牌槽取值：浅色优先，缺失时用深色兜底
    // ⚠ 键名带 `--` 前缀（extractDecls 的输出形式），而映射表用 tweakcn 的裸名
    const pick = (slot) => light[`--${slot}`] ?? dark[`--${slot}`];

    const brand = {};
    for (const [slot, bvSlot] of Object.entries(TO_BIVANE)) {
        const value = pick(slot);
        if (value === undefined) continue;
        brand[bvSlot] = normalizeColor(value);
    }

    // chart 槽的角色约定：chart-1=主色 / chart-2=成功 / chart-3=警告
    // 主色已经在 TO_BIVANE 里由 primary 给出；这里只补成功/警告两个
    for (const [chartSlot, role] of Object.entries(CHART_ROLE)) {
        if (role === 'primary') continue;
        const value = pick(chartSlot);
        if (value === undefined) continue;
        const bvSlot = role === 'success' ? '--bv-green' : '--bv-orange';
        if (brand[bvSlot] === undefined) brand[bvSlot] = normalizeColor(value);
    }

    const entries = Object.entries(brand);
    const body = entries.map(([k, v]) => `    ${k}: ${v};`).join('\n');

    return `/**
 * ${className} · 由 tweakcn 主题导入生成（Bivane 品牌风格）
 *
 * 用法：<html class="bv-theme-${className}">，可与 bv-theme-dark 叠加。
 *
 * ⚠ 本文件由 scripts/tweakcn-bridge.mjs 生成，勿手改。
 *
 * 只覆盖品牌槽（--bv-blue / --bv-red / --bv-green / --bv-orange …）——
 * 中性槽（文本 / 边框 / 底色）由 Bivane 的 Vant 复刻基线统一保证，
 * 不允许被外部主题改写（理由见 packages/tokens/tweakcn/mapping.mjs）。
 */
.bv-theme-${className} {
${body}
}
`;
}

/* ─────────────────────────── CLI ─────────────────────────── */

function parseArgs(argv) {
    const args = { _: [] };
    for (let i = 0; i < argv.length; i += 1) {
        const a = argv[i];
        if (a.startsWith('--')) {
            const key = a.slice(2);
            const next = argv[i + 1];
            if (next && !next.startsWith('--')) {
                args[key] = next;
                i += 1;
            } else {
                args[key] = true;
            }
        } else {
            args._.push(a);
        }
    }
    return args;
}

function main() {
    const args = parseArgs(process.argv.slice(2));
    const cmd = args._[0];

    if (cmd === 'export') {
        // 消费者项目里没有本仓的 tokens 源文件 —— export 只在 Bivane 仓库内可用。
        // 消费者拿到的 styles/bivane/tweakcn.css 是**预生成**的产物，直接用即可。
        if (!existsSync(join(STYLES_DIR, 'vant.css'))) {
            console.error(
                'export 只能在 Bivane 仓库内运行（需要 packages/tokens/styles/ 下的源文件）。\n' +
                    '你若是在消费者项目里：直接用预生成产物 styles/bivane/tweakcn.css，\n' +
                    '把它贴进 tweakcn 的 Import Custom CSS 即可。',
            );
            process.exit(1);
        }
        const styleFile = args.style
            ? join(STYLES_DIR, `vant-${args.style}.css`)
            : null;
        if (styleFile && !existsSync(styleFile)) {
            console.error(`找不到风格文件：${styleFile}`);
            process.exit(1);
        }
        const tokens = readBivaneTokens(styleFile ? [styleFile] : []);
        const name = args.style ? `Bivane ${args.style}` : 'Bivane';
        const css = buildExport(tokens, { name });
        if (args.out) {
            writeFileSync(args.out, css, 'utf8');
            console.log(`已写入 ${args.out}（${css.length} 字节）`);
        } else {
            process.stdout.write(css);
        }
        return;
    }

    if (cmd === 'import') {
        const input = args._[1];
        const name = args.name ?? 'custom';
        if (!input) {
            console.error('用法：tweakcn-bridge import <tweakcn.css> --name <name>');
            process.exit(1);
        }
        const css = importTweakcnCss(readFileSync(input, 'utf8'), name);
        if (args.out) {
            writeFileSync(args.out, css, 'utf8');
            console.log(`已写入 ${args.out}（${css.length} 字节）`);
        } else {
            process.stdout.write(css);
        }
        return;
    }

    console.error(
        '用法：\n' +
            '  tweakcn-bridge export [--style ocean|grape] [--out <file>]\n' +
            '  tweakcn-bridge import <tweakcn.css> --name <name> [--out <file>]',
    );
    process.exit(1);
}

// 仅在被直接执行时跑 CLI（被 import 时不跑）
if (process.argv[1] && resolve(process.argv[1]) === resolve(fileURLToPath(import.meta.url))) {
    main();
}

/**
 * Bivane · CSS 变量提取器（零依赖）
 *
 * 用途：tweakcn 双向桥接的底层工具。**故意不依赖 postcss** ——
 * 消费者 `npx shadcn add @bivane/tweakcn` 后要能直接跑这个脚本，
 * 若依赖 postcss 就得给消费者装一个包（体积 + 供应链面）。
 * 正解性的保证来自 tests/tweakcn-bridge.test.ts：**用 postcss 做交叉验证**
 * （postcss 是本仓 devDependency，测试里拿它当「真值」比对本模块的输出）。
 *
 * ── 为什么不能用正则硬啃 ─────────────────────────────────────────
 * 1. 注释里可能有 `}`：vant.css 有一段注释内嵌了 `.van-popup--center { max… }`，
 *    用 `\{([^}]*)\}` 提块会在这里**提前截断**，后半张表全丢。
 * 2. 选择器与花括号之间可能有注释：`:root` 与 `, :host` 之间夹一段注释。
 * 3. 声明值里可能有分号（自定义属性里尤其常见）：`--x: a; b;`。
 * 所以这里手写一个**够用但正确**的小解析器：
 * 先剥注释（等长替换，保留字符位置），再按括号配平提块。
 */

/** 剥掉 CSS 注释，用等长空格替换以保留字符位置 */
export function stripComments(css) {
    let out = '';
    let i = 0;
    const n = css.length;
    while (i < n) {
        const c = css[i];
        if (c === '/' && css[i + 1] === '*') {
            const end = css.indexOf('*/', i + 2);
            const stop = end === -1 ? n : end + 2;
            // 换成等长空白：保持后续所有偏移不变
            out += ' '.repeat(stop - i);
            i = stop;
            continue;
        }
        out += c;
        i += 1;
    }
    return out;
}

/**
 * 找出所有「选择器 → 块体」的映射。
 *
 * 只处理**顶层**规则（不递归进 @media / @supports）——
 * 桥接场景只需要 :root / .dark / .bv-theme-* 这类顶层块。
 *
 * @returns Map<string, string[]>  选择器（已归一化空白）→ 块体数组
 */
export function extractBlocks(css) {
    const src = stripComments(css);
    const map = new Map();
    let i = 0;
    const n = src.length;

    while (i < n) {
        // 找到下一个顶层 '{'
        const brace = src.indexOf('{', i);
        if (brace === -1) break;

        const selector = src.slice(i, brace).trim();
        // 块体起点
        let depth = 1;
        let j = brace + 1;
        while (j < n && depth > 0) {
            if (src[j] === '{') depth += 1;
            else if (src[j] === '}') depth -= 1;
            j += 1;
        }
        const body = src.slice(brace + 1, depth === 0 ? j - 1 : n);

        // 只收顶层规则：选择器里若含 '{' 说明前面跳过了嵌套（@media 等）
        if (selector && !selector.includes('@') && !selector.includes('{')) {
            const key = selector.replace(/\s+/g, ' ').trim();
            const list = map.get(key) ?? [];
            list.push(body);
            map.set(key, list);
        }

        // 若块体内部还有嵌套（@media），需要跳过它的内容继续找顶层块
        if (depth > 0) {
            // 找与这个 '{' 配平的 '}'，从那里继续
            let d = 1;
            let k = brace + 1;
            while (k < n && d > 0) {
                if (src[k] === '{') d += 1;
                else if (src[k] === '}') d -= 1;
                k += 1;
            }
            i = k;
        } else {
            i = j;
        }
    }
    return map;
}

/**
 * 从块体里提取自定义属性声明。
 *
 * 值里可能有分号（`--x: a; b` 里的 `;` 属于值的一部分），
 * 所以按「分号分隔，但跳过引号内与括号内」来切。
 *
 * @returns Record<string, string>  变量名 → 原始值（未 trim 内部空白）
 */
export function extractDecls(body) {
    const out = {};
    const s = stripComments(body);
    let i = 0;
    const n = s.length;
    let start = 0;

    const push = (from, to) => {
        const chunk = s.slice(from, to);
        const colon = chunk.indexOf(':');
        if (colon === -1) return;
        const name = chunk.slice(0, colon).trim();
        const value = chunk.slice(colon + 1).trim();
        if (!name.startsWith('--')) return;
        out[name] = value;
    };

    while (i < n) {
        const c = s[i];
        if (c === '"' || c === "'") {
            // 跳过字符串
            const quote = c;
            i += 1;
            while (i < n && s[i] !== quote) {
                if (s[i] === '\\') i += 1;
                i += 1;
            }
            i += 1;
            continue;
        }
        if (c === '(') {
            let d = 1;
            i += 1;
            while (i < n && d > 0) {
                if (s[i] === '(') d += 1;
                else if (s[i] === ')') d -= 1;
                i += 1;
            }
            continue;
        }
        if (c === ';') {
            push(start, i);
            start = i + 1;
        }
        i += 1;
    }
    push(start, n);
    return out;
}

/**
 * 把一组 CSS 文件解析成「作用域 → 变量表」。
 *
 * @param {string[]} files           CSS 文件内容
 * @param {string[]} scopeSelectors  哪些选择器算「作用域」（如 [':root, :host']）
 * @returns Record<string, Record<string,string>>
 */
export function collectScopes(files, scopeSelectors) {
    const scopes = {};
    for (const css of files) {
        const blocks = extractBlocks(css);
        for (const [selector, bodies] of blocks) {
            if (!scopeSelectors.includes(selector)) continue;
            const bucket = (scopes[selector] ??= {});
            for (const body of bodies) {
                Object.assign(bucket, extractDecls(body));
            }
        }
    }
    return scopes;
}

/**
 * 解析 `var(--x)` 引用链，返回字面量。
 *
 * CSS 自定义属性是**延迟解析**的：`--bv-primary: var(--bv-blue)` 在
 * `.bv-theme-ocean` 作用域内会解析成 ocean 的 --bv-blue。
 * 这里做同样的事：按作用域合并后逐层解引用。
 *
 * @param {Record<string,string>} scope  变量表（含各级）
 * @param {string} name                 变量名
 * @returns {string|null}               解引用后的字面量；无法解析时返回 null
 */
export function resolveVar(scope, name) {
    const seen = new Set();
    const walk = (key) => {
        if (seen.has(key)) return null;
        seen.add(key);
        const raw = scope[key];
        if (raw === undefined) return null;
        const m = /^var\(\s*(--[a-zA-Z0-9_-]+)\s*\)$/.exec(raw);
        if (m) return walk(m[1]);
        return raw;
    };
    return walk(name);
}

/**
 * 判断一个值是否是「可安全交给 culori 的颜色字面量」。
 *
 * tweakcn 的导入器对颜色槽做 `culori.parse(value)`，
 * 解析失败会静默变成空 —— 所以导出前必须自查。
 */
export function isColorLiteral(value) {
    if (!value) return false;
    const v = value.trim();
    return (
        /^#[0-9a-fA-F]{3,8}$/.test(v) ||
        /^rgb\(/i.test(v) ||
        /^rgba\(/i.test(v) ||
        /^hsl\(/i.test(v) ||
        /^hsla\(/i.test(v) ||
        /^oklch\(/i.test(v) ||
        /^oklab\(/i.test(v) ||
        /^color\(/i.test(v)
    );
}

/**
 * Bivane · 颜色字面量归一化（零依赖）
 *
 * 用途：tweakcn 桥接的导入方向。
 * tweakcn 生态的默认主题用 `oklch(...)`（shadcn v4 就是），
 * 用户手写的主题也常用 oklch / hsl / rgb。但 Bivane 的 token 体系是 **hex 基线**
 * （vant.css 里 40 处裸色值全是 hex），导入产物若混进 oklch 会与库内其它
 * 风格文件（vant-ocean.css 等）不一致，也不好肉眼比对。
 * 所以这里统一转成 hex。
 *
 * 色彩空间换算走 **sRGB**（IEC 61966-2-1），与 culori / tweakcn 的默认行为一致。
 * 转出的 hex 一律 6 位小写（culori.formatHex 的格式）。
 *
 * ⚠ 精度：oklch → sRGB 需要 gamut 裁剪（超出 sRGB 的色相会被裁到边界），
 *   裁剪后可能有微小色差（ΔE < 0.01）。这是任何 hex 目标格式的固有代价 ——
 *   保留 oklch 原文才能无损，但那样产物就不是 hex 基线了。
 */

/**
 * 已经处于 **sRGB 空间**的 0..1 通道值 → 8bit。
 * hsl() 的输出天然在 sRGB 空间（定义即如此），不能再过一遍传递函数
 * —— 过了就等于把亮度整体抬高（曾导致 hsl(217,100%,53%) 算出 #45adff 而非 #0f6bff）。
 */
function fromSrgb(channel) {
    return Math.round(Math.min(1, Math.max(0, channel)) * 255);
}

/**
 * 把 **线性** sRGB 的 0..1 通道值转成 8bit（要过 sRGB 传递函数）。
 * 只用于 oklch/oklab —— 那两个色彩空间换算出来的就是线性 sRGB。
 */
function encodeSrgb(channel) {
    const c = channel <= 0.0031308 ? channel * 12.92 : 1.055 * Math.pow(channel, 1 / 2.4) - 0.055;
    return Math.round(Math.min(1, Math.max(0, c)) * 255);
}

function toHexPair(r, g, b) {
    const hex = (n) => n.toString(16).padStart(2, '0');
    return `#${hex(r)}${hex(g)}${hex(b)}`;
}

/** hex → [r,g,b] 0..255 */
function hexToRgb(hex) {
    let h = hex.replace('#', '').toLowerCase();
    if (h.length === 3 || h.length === 4) h = h.split('').map((c) => c + c).join('');
    if (h.length === 8) h = h.slice(0, 6);
    if (!/^[0-9a-f]{6}$/.test(h)) return null;
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
}

/**
 * hsl → [r,g,b] 0..255（h 单位为度，s/l 为 0..100）
 *
 * 标准换算：k(n) = (n + h/30) % 12；a = s·min(l, 1-l)；
 *           f(n) = l - a·max(-1, min(k(n)-3, 9-k(n), 1))
 * 注意 min 是**三参数**（k-3、9-k、1 同时参与）—— 写成两层嵌套 min 会算错。
 */
function hslToRgb(h, s, l) {
    const sat = s / 100;
    const lig = l / 100;
    const k = (n) => (n + h / 30) % 12;
    const a = sat * Math.min(lig, 1 - lig);
    const f = (n) => lig - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
    return [fromSrgb(f(0)), fromSrgb(f(8)), fromSrgb(f(4))];
}

/**
 * oklch → [r,g,b] 0..255
 *
 * OKLab → 线性 sRGB 的逆变换（参考 Björn Ottosson 的推导）：
 *   l' = L + 0.3963377774·a + 0.2158037573·b
 *   m' = L - 0.1055613458·a - 0.0638541728·b
 *   s' = L - 0.0894841775·a - 1.2914855480·b
 *   l = l'³, m = m'³, s = s'³
 *   r =  4.0767416621·l - 3.3077115913·m + 0.2309699292·s
 *   g = -1.2684380046·l + 2.6097574011·m - 0.3413193965·s
 *   b =  -0.0041960863·l - 0.7034186147·m + 1.7076147010·s
 * 其中 a = C·cos(h°)、b = C·sin(h°)
 */
function oklchToRgb(L, C, hDeg) {
    const hRad = (hDeg * Math.PI) / 180;
    const a = C * Math.cos(hRad);
    const b = C * Math.sin(hRad);

    const l_ = L + 0.3963377774 * a + 0.2158037573 * b;
    const m_ = L - 0.1055613458 * a - 0.0638541728 * b;
    const s_ = L - 0.0894841775 * a - 1.291485548 * b;

    const l = l_ * l_ * l_;
    const m = m_ * m_ * m_;
    const s = s_ * s_ * s_;

    const lr = 4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s;
    const lg = -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s;
    const lb = -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s;

    // ⚠ 这里出来的是**线性** sRGB，必须再过一次 sRGB 传递函数才是 8bit 值。
    //    encodeSrgb 内部已经做了「传递函数 + 夹取 + x255」三件事，
    //    所以这里**不能**再额外套一层 gamma —— 套两层会把颜色整体提亮
    //    （曾导致 oklch(0.145 0 0) 算出 #383838 而非 #0a0a0a）。
    return [encodeSrgb(lr), encodeSrgb(lg), encodeSrgb(lb)];
}

/** 解析 CSS 颜色函数里的数字与百分比（统一成 0..1 或按需的原始值） */
function parseNumber(token, scale = 1) {
    const t = token.trim();
    if (t.endsWith('%')) return (parseFloat(t) / 100) * scale;
    return parseFloat(t) * scale;
}

/**
 * 把任意 CSS 颜色字面量归一化成 6 位小写 hex。
 * 认得的格式：#hex / rgb() / rgba() / hsl() / hsla() / oklch() / oklab()
 * 认不得时**原样返回**（不猜、不丢）—— 调用方据此判断是否需要报警。
 */
export function normalizeColor(value) {
    if (!value) return value;
    const v = value.trim();

    if (v.startsWith('#')) {
        const rgb = hexToRgb(v);
        return rgb ? toHexPair(rgb[0], rgb[1], rgb[2]) : v;
    }

    const fn = /^([a-zA-Z-]+)\((.*)\)$/s.exec(v);
    if (!fn) return v;
    const name = fn[1].toLowerCase();
    const body = fn[2];

    // 按逗号切分（rgb/hsl 的旧语法），或按空格切分（现代语法）
    const parts = body
        .split(/[\s,/]+/)
        .map((p) => p.trim())
        .filter(Boolean);

    try {
        if (name === 'rgb' || name === 'rgba') {
            // rgb() 的通道是 0..255（不是 0..1）；写成百分比时才按 100 折算
            const chan = (tok) => {
                const t = tok.trim();
                if (t.endsWith('%')) return Math.round((parseFloat(t) / 100) * 255);
                return Math.round(parseFloat(t));
            };
            return toHexPair(chan(parts[0]), chan(parts[1]), chan(parts[2]));
        }
        if (name === 'hsl' || name === 'hsla') {
            const h = parseFloat(parts[0]);
            // hsl 的 s/l：写百分比就除 100；写裸数字就是 0..100 的绝对值
            const pct = (tok) => (tok.trim().endsWith('%') ? parseFloat(tok) : parseFloat(tok));
            const s = pct(parts[1]);
            const l = pct(parts[2]);
            const rgb = hslToRgb(h, s, l);
            return toHexPair(rgb[0], rgb[1], rgb[2]);
        }
        if (name === 'oklch') {
            // oklch(L C H) —— L 是 0..1，C 是 0..0.4 左右，H 是角度
            const L = parseNumber(parts[0]);
            const C = parseNumber(parts[1]);
            // 色相可以带 deg / rad / grad / turn 单位
            let h = parseFloat(parts[2]);
            const unit = /([a-zA-Z]+)\s*$/.exec(parts[2])?.[1]?.toLowerCase();
            if (unit === 'rad') h = (h * 180) / Math.PI;
            else if (unit === 'turn') h = h * 360;
            else if (unit === 'grad') h = (h * 360) / 400;
            const rgb = oklchToRgb(L, C, h);
            return toHexPair(rgb[0], rgb[1], rgb[2]);
        }
        if (name === 'oklab') {
            const L = parseNumber(parts[0]);
            const a = parseNumber(parts[1]);
            const b = parseNumber(parts[2]);
            // oklab → oklch（极坐标）
            const C = Math.sqrt(a * a + b * b);
            const h = (Math.atan2(b, a) * 180) / Math.PI;
            const rgb = oklchToRgb(L, C, h);
            return toHexPair(rgb[0], rgb[1], rgb[2]);
        }
    } catch {
        return v;
    }
    return v;
}

/** 判断归一化后是否仍是一个可被 culori 解析的颜色（用于「静默丢弃」预警） */
export function isConvertibleColor(value) {
    return normalizeColor(value) !== value.trim() || /^#[0-9a-f]{6}$/.test(normalizeColor(value));
}

/**
 * tweakcn 导入器的**逐字复刻**（来源：jnsahaj/tweakcn 仓库 utils/parse-css-input.ts）
 *
 * 这是桥接的「真值判定器」—— 我们不能只验证「我们的导出看起来对」，
 * 必须验证「tweakcn 自己的解析器能从中读出我们期望的值」。
 *
 * 原实现要点（逐条对齐）：
 *  1. extractCssBlockContent 用正则 `${selector}\s*{([^}]+)}` —— 要求**字面量**选择器，
 *     且块内不能出现 `}`。所以 `:root, :host {` 匹配不上 `:root`！
 *  2. variableNames = Object.keys(defaultThemeState.styles.light) —— 44 个名字，
 *     不在名单里的**直接丢弃**（不报错）。
 *  3. COMMON_STYLES 里的变量原样保留；其余走 processColorValue → colorFormatter(hex)。
 *  4. processColorValue：值以数字开头 → 当作 hsl 的裸通道值包成 hsl(...)。
 *  5. culori.parse 解析失败 → colorFormatter 捕获异常并**原样返回**（不抛）。
 *
 * 与原实现唯一的差别：colorFormatter 用我们自己的 hex 归一化代替 culori，
 * 因为本仓不引入 culori。归一化规则与 culori.formatHex 一致（转小写、补齐 6 位）。
 */

export const TWEAKCN_VARIABLE_NAMES = [
    'background', 'foreground', 'card', 'card-foreground', 'popover', 'popover-foreground',
    'primary', 'primary-foreground', 'secondary', 'secondary-foreground',
    'muted', 'muted-foreground', 'accent', 'accent-foreground',
    'destructive', 'destructive-foreground',
    'border', 'input', 'ring',
    'chart-1', 'chart-2', 'chart-3', 'chart-4', 'chart-5',
    'sidebar', 'sidebar-foreground', 'sidebar-primary', 'sidebar-primary-foreground',
    'sidebar-accent', 'sidebar-accent-foreground', 'sidebar-border', 'sidebar-ring',
    'font-sans', 'font-serif', 'font-mono',
    'radius',
    'shadow-color', 'shadow-opacity', 'shadow-blur', 'shadow-spread',
    'shadow-offset-x', 'shadow-offset-y',
    'letter-spacing', 'spacing',
];

export const TWEAKCN_COMMON_STYLES = [
    'font-sans', 'font-serif', 'font-mono', 'radius',
    'shadow-opacity', 'shadow-blur', 'shadow-spread',
    'shadow-offset-x', 'shadow-offset-y', 'letter-spacing', 'spacing',
];

function escapeRegExp(s) {
    return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** 原版：new RegExp(`${selector}\s*{([^}]+)}`)，取第一个匹配 */
export function extractCssBlockContent(input, selector) {
    const regex = new RegExp(`${escapeRegExp(selector)}\\s*{([^}]+)}`);
    return input.match(regex)?.[1]?.trim() || null;
}

/** 原版 processColorValue：值以数字开头 → 当裸 HSL 通道值 */
export function processColorValue(value) {
    return /^\d/.test(value) ? `hsl(${value})` : value;
}

/**
 * 归一化成 hex（对应 culori.formatHex）。
 * 只处理 hex 输入 —— tweakcn 导出的主题里颜色槽必然已是 hex（culori 转过了）。
 */
export function toHex(value) {
    const v = value.trim();
    const m = /^#([0-9a-fA-F]{3,8})$/.exec(v);
    if (!m) return v;
    let hex = m[1].toLowerCase();
    if (hex.length === 3) hex = hex.split('').map((c) => c + c).join('');
    if (hex.length === 4) hex = hex.split('').map((c) => c + c).join('');
    if (hex.length === 8) hex = hex.slice(0, 6);
    return `#${hex}`;
}

/** 原版 parseColorVariables */
function parseColorVariables(cssContent, target, validNames) {
    const variableDeclarations = cssContent.match(/--[^:]+:\s*[^;]+/g) || [];
    for (const declaration of variableDeclarations) {
        const [name, value] = declaration.split(':').map((p) => p.trim());
        const cleanName = name.replace('--', '');
        if (!validNames.includes(cleanName)) continue; // 不在名单 → 丢弃
        if (TWEAKCN_COMMON_STYLES.includes(cleanName)) {
            target[cleanName] = value;
            continue;
        }
        target[cleanName] = toHex(processColorValue(value));
    }
}

/** 原版 parseCssInput */
export function parseCssInput(input) {
    const lightColors = {};
    const darkColors = {};
    const rootContent = extractCssBlockContent(input, ':root');
    const darkContent = extractCssBlockContent(input, '.dark');
    if (rootContent) parseColorVariables(rootContent, lightColors, TWEAKCN_VARIABLE_NAMES);
    if (darkContent) parseColorVariables(darkContent, darkColors, TWEAKCN_VARIABLE_NAMES);
    return { lightColors, darkColors };
}
